def __find_main_schedule_window() -> bool:
    """Searches for the main Location Schedule UI window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the schedule_location.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(ScheduleLocation.location_Schedule_Window) is not None else False

def __find_location_directory_ro_window() -> bool:
    """Searches for the Location Directory RO UI window that appears when no previous location has been selected
    in the Schedule -> Location workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the schedule_location.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(ScheduleLocation.location_Directory_RO_Window) is not None else False

def __find_schedule_appointment_slip_window() -> bool:
    """Searches for the Appointment Slip UI window within the Schedule -> Location workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the schedule_location.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(ScheduleLocation.location_Appointment_Slip_Window) is not None else False

def __find_session_in_table(tablePane: dict, searchText: str, setCurrentSessionToStart: bool = True,
                            ocrTimeout: int = 3000) -> opt[object]:
    """Searches a schedule table pane for a session row using OCR.

    -> Hidden function that should not be used outside the context of the schedule_location.py file context!

    The Location Schedule and Daily Master tables are different controls in different dialogs,
    so the pane is a parameter rather than fixed.

    :param dict tablePane: Object map of the schedule table to search
    :param str searchText: Text to find, either a "time|last_name," row pattern or one fragment
    :param bool setCurrentSessionToStart: Whether to move the highlight to the first row first,
                                          since OCR cannot read a highlighted row
    :param int ocrTimeout: Time in milliseconds each search permutation waits
    :return: the found screen-area object, or None
    :rtype: object
    """
    if setCurrentSessionToStart:
        CommonActions.press_home_key()
    # No priming get_all_text_via_ocr_in_object() call here: waitForOcrText does its own OCR
    # pass, so reading the whole table first and discarding the result just paid for a second
    # full-table OCR on every search.
    return __find_obj_by_ocr_with_multiple_search_permutations(searchText, tablePane, ocrTimeout)

def __ocr_search_permutations(searchText: str) -> 'list[str]':
    """Builds the search strings to try, in order, for one piece of table text.

    -> Hidden function that should not be used outside the context of the schedule_location.py file context!

    Squish/Tesseract misreads vertical table rules as "/", "[", "{" and so on, and renders
    whitespace as underscores, so a literal search often misses. Each permutation covers one of
    those misreadings.

    Deduplicated, and that matters for speed: a permutation that only rewrites "|" leaves a
    search text without one completely unchanged, so the original ordering re-ran the identical
    query up to seven times, each waiting out its own OCR timeout. A time like "10:30" now costs
    two searches instead of ten.

    :param str searchText: The text as it is expected to read
    :return: search strings to try, in priority order, with no repeats
    :rtype: list[str]
    """
    candidates = [searchText]
    if "|" in searchText:
        candidates.append(searchText.replace("|", " |"))
    if "," in searchText:
        candidates.append(searchText.replace(",", "."))
    if "|" in searchText and "," in searchText:
        candidates.append(searchText.replace("|", " |").replace(",", "."))
    candidates.append("_" + searchText)
    if "|" in searchText:
        for replacement in ("/", "]", "[", "}", "{"):
            candidates.append(searchText.replace("|", replacement))

    ordered = []
    for candidate in candidates:
        if candidate not in ordered:
            ordered.append(candidate)
    return ordered

def __find_obj_by_ocr_with_multiple_search_permutations(searchText: str, tablePane: dict = None,
                                                        ocrTimeout: int = 3000) -> opt[object]:
    """Searches a table for text using OCR, trying each permutation until one matches.

    -> Hidden function that should not be used outside the context of the schedule_location.py file context!

    :param str searchText: The text as it is expected to read
    :param dict tablePane: Table to search; defaults to the Location Schedule table
    :param int ocrTimeout: Time in milliseconds each permutation waits
    :return: Found object or None if no permutation matched
    :rtype: object
    """
    if tablePane is None:
        tablePane = ScheduleLocation.location_Schedule_Window_Pane

    for candidate in __ocr_search_permutations(searchText):
        found_session_obj = CommonActions.get_object_by_ocr_text_in_object(tablePane, candidate, ocrTimeout)
        if found_session_obj is not None:
            return found_session_obj
    return None

