@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_entered_location_value_in_ro_window() -> str:
    """Searches for the Find value entered in the Location Directory RO window and returns the value as a string

    :return: Text value inside Squish object
    :rtype: str
    """
    location_value_pane = CommonActions.find_object(ScheduleLocation.location_Directory_RO_Window_Find_Value_Pane)
    return CommonActions.get_objects_text_value(location_value_pane)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_current_location_value_in_schedule_location_window() -> str:
    """Finds and returns the current value of the Location textbox of the Location Schedule UI window.

    :return: Currently entered value of the Location textbox of the Location Schedule UI.
    :rtype: str
    """
    if not __find_main_schedule_window():
        raise RuntimeError()
    location_value_box = CommonActions.find_object(ScheduleLocation.location_Schedule_Window_Location_Textbox)
    return CommonActions.get_objects_text_value(location_value_box)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_and_confirm_location_value_in_location_schedule_window(locationValue: str):
    """Clears the current value in the Location Textbox of the Location Schedule window, and types the given locationValue into said textbox.

    :param locationValue: Given string value of the location to be entered into the Location textbox.
    :type locationValue: str
    """
    if not __find_main_schedule_window():
        raise RuntimeError("Unable to find the schedule window")
    CommonActions.press_key_sequence("<Shift+Ctrl+a>")
    CommonActions.press_delete_key()
    CommonActions.type_in_textfield(ScheduleLocation.location_Schedule_Window_Location_Textbox, locationValue)
    CommonActions.press_tab_key()

