@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_daily_master_schedule_open(waitTimeout: int = 15000) -> bool:
    """Reports whether the Daily Master schedule window is open.

    :param int waitTimeout: Time in milliseconds to wait before reporting it absent
    :return: True or False
    :rtype: bool
    """
    return CommonActions.does_object_exist(DailyMasterSchedule.ui_Main_Window, waitTimeout)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_daily_master_schedule_window_title() -> str:
    """Returns the caption of the Daily Master schedule window.

    Formatted " <date>  <DAY> - Daily Master Schedule: <department>", e.g.
    " 9/21/2026  MON - Daily Master Schedule: MO", so it carries both the day on display and
    the department -- the only parts of this view readable without OCR.

    :return: the window caption
    :rtype: str
    """
    return CommonActions.get_uneditable_field_objects_text_value(DailyMasterSchedule.ui_Main_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_daily_master_department() -> str:
    """Returns the department the Daily Master schedule is scoped to.

    Read off the window caption's trailing ": <department>" rather than the Department
    dropdown, whose own text is the label "Department:" rather than the selected value.

    :return: the department code, e.g. "MO", or "" when the caption is not in that shape
    :rtype: str
    """
    caption = get_daily_master_schedule_window_title()
    return caption.rsplit(":", 1)[-1].strip() if ":" in caption else ""

