@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_daily_master_row_counter_text() -> str:
    """Returns the Daily Master row counter verbatim, e.g. "0 / 2".

    :return: the counter text
    :rtype: str
    """
    if not is_daily_master_schedule_open():
        raise RuntimeError("Daily Master schedule window is not open")
    return CommonActions.get_uneditable_field_objects_text_value(DailyMasterSchedule.window_Row_Counter_Pane)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_daily_master_appointment_count() -> int:
    """Returns how many appointments the Daily Master schedule is showing.

    Read off the window's "<selected> / <total>" row counter, which tracks the table contents
    and needs no OCR -- the table is a ClaList that publishes only its scrollbars, so this is
    the one way to size the day's schedule on an installation with no Tesseract engine.

    :return: the total from the counter, or -1 when it cannot be read or parsed
    :rtype: int
    """
    counter = get_daily_master_row_counter_text()
    if "/" not in counter:
        return -1
    try:
        return int(counter.split("/")[-1].strip())
    except ValueError:
        return -1

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_daily_master_ocr_available() -> bool:
    """Reports whether OCR can read the Daily Master schedule table on this installation.

    Squish ships no OCR engine -- Tesseract installs separately -- and the table exposes no
    queryable rows, so probe with this before calling the readers below.

    :return: True or False
    :rtype: bool
    """
    if not is_daily_master_schedule_open():
        raise RuntimeError("Daily Master schedule window is not open")
    # Probed against the row counter, not the table: this only needs to know whether an engine
    # is configured, and OCR cost scales with the region, which the source image is upscaled
    # 3.5x before. Reading a two-character counter answers the same question as reading the
    # whole schedule, far quicker.
    return CommonActions.is_ocr_available(DailyMasterSchedule.window_Row_Counter_Pane)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_daily_master_schedule_text() -> str:
    """Returns everything OCR can read from the Daily Master schedule table.

    :return: OCR text of the schedule table, or an empty string when nothing could be read
    :rtype: str
    """
    if not is_daily_master_schedule_open():
        raise RuntimeError("Daily Master schedule window is not open")
    return str(CommonActions.get_all_text_via_ocr_in_object(DailyMasterSchedule.window_Table_Pane) or "")

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_daily_master_appointment_lines() -> 'list[str]':
    """Returns the non-empty lines OCR reads from the Daily Master schedule table, one per row.

    Line count is indicative, not exact: OCR can split or merge rows.

    :return: non-empty, stripped lines of the schedule table
    :rtype: list[str]
    """
    return [line.strip() for line in get_daily_master_schedule_text().splitlines() if line.strip()]

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def find_text_in_daily_master_table(searchText: str, setCurrentSessionToStart: bool = True,
                                     ocrTimeout: int = 3000) -> opt[object]:
    """Finds one piece of text in the Daily Master table and returns the object it matched.

    Returning the object lets a caller check for a row and then click it off a single OCR
    search. is_text_displayed_in_daily_master_table() followed by
    select_text_in_daily_master_table() pays for the same search twice.

    :param str searchText: Text to look for, e.g. "10:30" or "MSQ-84082,"
    :param bool setCurrentSessionToStart: Whether to move the highlight to the first row first,
                                          since OCR cannot read a highlighted row
    :param int ocrTimeout: Time in milliseconds each search permutation waits
    :return: the matched screen-area object, or None
    :rtype: object
    """
    return __find_session_in_table(DailyMasterSchedule.window_Table_Pane,
                                   searchText,
                                   setCurrentSessionToStart,
                                   ocrTimeout)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_found_table_object(foundObject: object) -> None:
    """Clicks an object returned by find_text_in_daily_master_table(), selecting its row.

    :param object foundObject: The screen-area object the OCR search matched
    :raises RuntimeError: when handed None, i.e. a search that found nothing
    """
    if foundObject is None:
        raise RuntimeError("No table object to select -- the OCR search found nothing")
    CommonActions.click_screen_area_object(foundObject)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_text_displayed_in_daily_master_table(searchText: str,
                                             setCurrentSessionToStart: bool = True) -> bool:
    """Reports whether any single piece of text can be found in the Daily Master table.

    Unlike is_session_displayed_in_daily_master_table(), which matches a whole
    "time|last_name," row pattern, this searches for one fragment -- a time, or a patient last
    name -- on its own. Searching the two separately says WHICH half OCR could not read when a
    row lookup fails, and avoids hanging the match on the vertical rule between them, which
    Tesseract renders variously as "/", "[", "{".

    :param str searchText: Text to look for, e.g. "10:30" or "MSQ-84082,"
    :param bool setCurrentSessionToStart: Whether to move the highlight to the first row first,
                                          since OCR cannot read a highlighted row
    :return: True or False
    :rtype: bool
    """
    return __find_session_in_table(DailyMasterSchedule.window_Table_Pane,
                                   searchText,
                                   setCurrentSessionToStart) is not None

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_text_in_daily_master_table(searchText: str,
                                       setCurrentSessionToStart: bool = True) -> None:
    """Finds one piece of text in the Daily Master table and clicks it, selecting its row.

    :param str searchText: Text to look for, e.g. "10:30" or "MSQ-84082,"
    :param bool setCurrentSessionToStart: Whether to move the highlight to the first row first,
                                          since OCR cannot read a highlighted row
    :raises RuntimeError: when the text cannot be found
    """
    found_obj = __find_session_in_table(DailyMasterSchedule.window_Table_Pane,
                                        searchText,
                                        setCurrentSessionToStart)
    if found_obj is None:
        raise RuntimeError(f"'{searchText}' not found in the Daily Master table")
    CommonActions.click_screen_area_object(found_obj)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_session_displayed_in_daily_master_table(timeLastNameSessionSelector: str,
                                               setCurrentSessionToStart: bool = True) -> bool:
    """Reports whether a session row can be found in the Daily Master schedule table.

    :param str timeLastNameSessionSelector: Time and Patient last name, e.g. "8:15|Bond,"
    :param bool setCurrentSessionToStart: Whether to move the highlight to the first row first,
                                          since OCR cannot read a highlighted row
    :return: True or False
    :rtype: bool
    """
    return __find_session_in_table(DailyMasterSchedule.window_Table_Pane,
                                   timeLastNameSessionSelector,
                                   setCurrentSessionToStart) is not None

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_patient_session_from_daily_master_table(timeLastNameSessionSelector: str,
                                                   setCurrentSessionToStart: bool = True) -> None:
    """Searches and selects a session row from the Daily Master schedule table using OCR.

    Same selector format as select_patient_session_from_location_schedule_table() -- see that
    function for why the "time|last_name," punctuation matters.

    :param str timeLastNameSessionSelector: Time and Patient last name text string to search
    :param bool setCurrentSessionToStart: Whether to set the current highlighted session to the
                                          first row, to help with OCR performance
    :raises RuntimeError: when the session cannot be found
    """
    session_obj = __find_session_in_table(DailyMasterSchedule.window_Table_Pane,
                                          timeLastNameSessionSelector,
                                          setCurrentSessionToStart)
    if session_obj is None:
        raise RuntimeError(f"Session '{timeLastNameSessionSelector}' not found in the Daily Master table")
    CommonActions.click_screen_area_object(session_obj)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_location_schedule_window_title() -> str:
    """Returns the caption of the Location Schedule window.

    The caption is the only part of this view readable without OCR -- the schedule table itself
    exposes no queryable rows -- so it is what a test can assert on where no OCR engine is
    configured.

    :return: the window caption, e.g. "<location> Location Schedule"
    :rtype: str
    """
    return CommonActions.get_uneditable_field_objects_text_value(ScheduleLocation.location_Schedule_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_location_schedule_ocr_available() -> bool:
    """Reports whether OCR can read the Location Schedule table on this installation.

    get_location_schedule_text(), get_location_schedule_appointment_lines(),
    is_session_displayed_in_location_schedule_table() and
    select_patient_session_from_location_schedule_table() all raise without an OCR engine; probe
    with this first if a missing engine should be reported rather than thrown.

    :return: True or False
    :rtype: bool
    """
    if not __find_main_schedule_window():
        raise RuntimeError("Unable to find the schedule window")
    return CommonActions.is_ocr_available(ScheduleLocation.location_Schedule_Window_Pane)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_location_schedule_text() -> str:
    """Returns everything OCR can read from the Location Schedule table.

    The schedule table exposes no queryable rows, so OCR is the only way to read what the day
    holds. Text is returned verbatim, including the OCR artefacts described in
    select_patient_session_from_location_schedule_table() -- vertical rules read as "/", "[",
    "{" and whitespace as "_" -- so match leniently rather than comparing exact strings.

    :return: OCR text of the schedule table, or an empty string when nothing could be read
    :rtype: str
    """
    if not __find_main_schedule_window():
        raise RuntimeError("Unable to find the schedule window")
    return str(CommonActions.get_all_text_via_ocr_in_object(ScheduleLocation.location_Schedule_Window_Pane) or "")

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_location_schedule_appointment_lines() -> 'list[str]':
    """Returns the non-empty lines OCR reads from the Location Schedule table, one per row.

    Line count is indicative, not exact: OCR can split or merge rows. Use it to assert the day
    is populated, and is_session_displayed_in_location_schedule_table() to assert a specific
    appointment.

    :return: non-empty, stripped lines of the schedule table
    :rtype: list[str]
    """
    return [line.strip() for line in get_location_schedule_text().splitlines() if line.strip()]

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_session_displayed_in_location_schedule_table(timeLastNameSessionSelector: str,
                                                    setCurrentSessionToStart: bool = True) -> bool:
    """Reports whether a session row can be found in the Location Schedule table.

    Same OCR lookup and same selector format as
    select_patient_session_from_location_schedule_table(), but returns a bool instead of
    clicking, so a missing appointment is a reportable result rather than a click on None.

    :param str timeLastNameSessionSelector: Time and Patient last name, e.g. "8:15|Bond,"
    :param bool setCurrentSessionToStart: Whether to move the highlight to the first row first,
                                          since OCR cannot read a highlighted row
    :return: True or False
    :rtype: bool
    """
    if not __find_main_schedule_window():
        raise RuntimeError("Unable to find the schedule window")
    if setCurrentSessionToStart:
        CommonActions.press_home_key()
    CommonActions.get_all_text_via_ocr_in_object(ScheduleLocation.location_Schedule_Window_Pane)
    return __find_obj_by_ocr_with_multiple_search_permutations(timeLastNameSessionSelector) is not None

