def __get_appointment_slip_field_text(objectMap: dict) -> str:
    """Reads one field of the Appointment Slip window.

    -> Hidden function that should not be used outside the context of the schedule_location.py file context!

    Uses get_uneditable_field_objects_text_value(), which resolves through waitForObjectExists:
    it neither moves the mouse (these are reads, not interactions) nor goes through
    find_object(), whose missing-object fallback returns the first Edit in the AUT and would
    hand back a different field's text as if it were this one.

    :param dict objectMap: Object map of the field to read
    :raises RuntimeError: when the Appointment Slip window is not open
    :return: the field's text
    :rtype: str
    """
    if not is_appointment_slip_open():
        raise RuntimeError("Appointment Slip window is not open")
    return CommonActions.get_uneditable_field_objects_text_value(objectMap)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_patient_in_appointment_slip() -> str:
    """Returns the Patient shown on the Appointment Slip window.

    Opening the slip while a patient chart is open pre-populates this field, so this is how a
    test confirms the slip picked up the intended patient instead of typing one in.

    :return: the patient as displayed, e.g. "MSQ-84082, LUNGPATIENT"
    :rtype: str
    """
    return __get_appointment_slip_field_text(ScheduleLocation.location_Appointment_Slip_Window_Patient_TextBox)

