@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_cancel_button_in_appointment_slip_window() -> None:
    """Dismisses the Appointment Slip window without saving, and waits for it to close.

    Cancel rather than OK: OK commits the slip, which would write an appointment change to the
    schedule. A read-only check must leave the schedule as it found it.
    """
    if is_appointment_slip_open():
        CommonActions.left_click_object(ScheduleLocation.location_Appointment_Slip_Window_Cancel_Button)
        CommonActions.wait_for_object_to_disappear(ScheduleLocation.location_Appointment_Slip_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def type_activity_in_appointment_slip(activityString: str) -> None:
    """Searches for the Activity text box in the Appointment Slip UI window and enters the given string.

    :param str activityString: String variable to be entered into the Activity text box
    """
    if __find_schedule_appointment_slip_window():
        CommonActions.left_click_object(ScheduleLocation.location_Appointment_Slip_Window_Activity_TextBox)
        CommonActions.press_key_sequence_ctrl_a()
        CommonActions.press_delete_key()
        CommonActions.type_in_textfield(ScheduleLocation.location_Appointment_Slip_Window_Activity_TextBox, activityString)
        CommonActions.press_tab_key()

