@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def type_appointments_number_in_appointment_slip_window(appointmentNumber: int) -> None:
    """Searches for the Appointments text box in the Appointment Slip UI window and enters the given int.

    The int variable is converted to a string as a part of the function.

    :param int appointmentNumber: Int variable to be entered into the Appointments text box
    """
    if __find_schedule_appointment_slip_window():
        CommonActions.left_click_object(ScheduleLocation.location_Appointment_Slip_Window_Appointments_TextBox)
        if int(CommonActions.get_objects_text_value(CommonActions.find_object(ScheduleLocation.location_Appointment_Slip_Window_Appointments_TextBox)).strip()) >= 1:
            CommonActions.press_key_sequence("<Down>")
        elif int(CommonActions.get_objects_text_value(CommonActions.find_object(ScheduleLocation.location_Appointment_Slip_Window_Appointments_TextBox)).strip()) < 1:
            CommonActions.press_key_sequence("<Down>")
            CommonActions.press_delete_key()
        CommonActions.type_in_textfield(ScheduleLocation.location_Appointment_Slip_Window_Appointments_TextBox, str(appointmentNumber))

