@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_view_patient_schedule_ui() -> None:
    if __find_main_schedule_window() is False:
        raise RuntimeError()
    CommonActions.right_click_object(ScheduleLocation.location_Schedule_Window)
    CommonActions.find_object(ScheduleLocation.location_Schedule_Window_Context_Menu)
    CommonActions.left_click_object(ScheduleLocation.location_Schedule_Window_Context_Menu_View_Patient_Schedule_MenuItem)
    CommonActions.find_object(ScheduleLocation.location_Schedule_View_Patient_Schedule_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def toggle_display_open_slots(enabled: bool) -> None:
    if __find_main_schedule_window() is False:
        raise
    CommonActions.right_click_object(ScheduleLocation.location_Schedule_Window)
    CommonActions.find_object(ScheduleLocation.location_Schedule_Window_Context_Menu)
    CommonActions.left_click_object(ScheduleLocation.location_Schedule_Window_Context_Menu_Preferences_MenuItem)
    display_obj = CommonActions.find_object(ScheduleLocation.location_Schedule_Window_Context_Menu_Preferences_SubMenuItem_Display_Open_Slots_MenuItem)
    if display_obj.enabled != enabled: #type: ignore
        CommonActions.left_click_object(display_obj)
    else:
        CommonActions.left_click_object(ScheduleLocation.location_Schedule_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def toggle_underline_display(enabled: bool) -> None:
    if __find_main_schedule_window() is False:
        raise
    CommonActions.right_click_object(ScheduleLocation.location_Schedule_Window)
    CommonActions.find_object(ScheduleLocation.location_Schedule_Window_Context_Menu)
    CommonActions.left_click_object(ScheduleLocation.location_Schedule_Window_Context_Menu_Preferences_MenuItem)
    underline_obj = CommonActions.find_object(ScheduleLocation.location_Schedule_Window_Context_Menu_Preferences_SubMenuItem_Display_Underline_MenuItem)
    if underline_obj.enabled != enabled: #type: ignore
        CommonActions.left_click_object(underline_obj)
    else:
        CommonActions.press_esc_key()

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_patient_session_in_view_patient_schedule(appointmentTime: str) -> None:
    text = CommonActions.get_all_text_via_ocr_in_object(ScheduleLocation.location_Schedule_View_Patient_Schedule_Appointment_Pane)
    appointment_time_obj = CommonActions.get_object_by_ocr_text_in_object(ScheduleLocation.location_Schedule_View_Patient_Schedule_Appointment_Pane, appointmentTime)
    CommonActions.click_screen_area_object(appointment_time_obj)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_patient_session_from_location_schedule_table(timeLastNameSessionSelector: str,
                                                        setCurrentSessionToStart: bool = True) -> None:
    """Searches and selects a session row from the Location Schedule table window using OCR.

    IMPORTANT: The session string argument to be searched MUST be in the format "time|last_name,".
    The time should be followed by a vertical line "|" and the patient last name should be followed
    by a comma ",".

    e.g. "8:15|Bond," or "9AM|Pryde,"

    Squish/ Tesseract's OCR implementation uses white space as the string delimiters to
    identify substrings in a string. As a result, it is recommended that search strings are in
    the format specified as this has been found through trial and error to be the most reliable
    method when using OCR.

    :param str timeLastNameSessionSelector: Time and Patient last name text string to search
    :param bool setCurrentSessionToStart: Whether to set the current highlighted session to
                                          to the first row, to help with OCR performance
    """

    if setCurrentSessionToStart:
        # Set the current highlighted session in the table to the first row. This might be required
        # as OCR is unable to read text from a row that is currently highlighted
        CommonActions.press_home_key()

    text = CommonActions.get_all_text_via_ocr_in_object(ScheduleLocation.location_Schedule_Window_Pane)
    session_obj = __find_obj_by_ocr_with_multiple_search_permutations(timeLastNameSessionSelector)
    CommonActions.click_screen_area_object(session_obj)

