    if __find_queue_patient_window() is False:
        raise
    CommonActions.type_in_textfield(ScheduleLocation.queuePatient_Location_Textbox, location)
    CommonActions.press_enter_key()
    CommonActions.left_click_object(ScheduleLocation.queuePatient_OK_Button)
    CommonActions.wait_for_object_to_disappear(ScheduleLocation.queuePatient_Main_Window)